    p1.push_back(Point_2(p.x(), p.y()));
}
for (const auto& p : P2.vectorPoints()) {
    p2.push_back(Point_2(p.x(), p.y()));
}

Pwh_list_2 diff_result;
CGAL::difference(p1, p2, std::back_inserter(diff_result));

for (const auto& pwh : diff_result) {
